1),(12452,615.276),(12453,641.979),(12454,1157.463),(12460,100.029),(12462,6.966),(12463,1083.6),(12469,112.8),(12470,135.934),(12471,126.85),(12472,137.493),(12473,125.915),(12475,266.6),(12476,274.125),(12477,256.925),(12478,262.3),(12479,96.75),(12480,12.9),(12549,184.0),(12550,187.05),(12552,145.125),(12560,10.0),(15001,23.718),(15002,28.623),(17310,16.744),(17777,237.938),(17778,237.938),(17779,237.938),(17780,237.938),(19202,149.963),(19203,820.0),(19204,374.1),(19205,52.245),(19206,195.435),(19207,135.45),(19208,132.236),(19209,216.795),(19210,86.494),(19212,83.205),(19924,298.108),(19926,221.229),(19938,148.35),(19939,145.306),(19940,145.306),(19941,385.611),(19942,32.133),(19943,32.133),(19944,32.133),(19945,105.886),(19947,119.041),(19950,253.955),(19951,212.059),(19952,272.878),(19960,95.484),(19962,155.191),(19964,198.816),(19965,212.059),(19966,180.367),(19968,268.288),(19972,670.729),(19977,206.412),(19978,169.281),(19979,169.281),(19980,198.816),(19988,324.65),(19989,324.65),(19990,324.65),(19998,17.217),(19999,16.744)
  ON CONFLICT (display_number) DO NOTHING;

  FOR rec IN
    SELECT np.display_number, np.new_price, p.id AS product_id
    FROM _new_prices np
    LEFT JOIN products p ON p.display_number = np.display_number AND p.legal_entity_id = v_le_id
  LOOP
    IF rec.product_id IS NULL THEN
      v_unmatched := v_unmatched + 1;
      CONTINUE;
    END IF;

    SELECT id, price, valid_from, valid_to INTO v_existing
    FROM price_list_items
    WHERE price_list_id = v_pl_id
      AND product_id = rec.product_id
      AND valid_from <= v_today
      AND (valid_to IS NULL OR valid_to >= v_today)
    ORDER BY valid_from DESC
    LIMIT 1;

    IF FOUND AND ABS(v_existing.price - rec.new_price) < 0.0001 THEN
      v_skipped := v_skipped + 1;
    ELSIF FOUND AND v_existing.valid_from = v_today THEN
      UPDATE price_list_items SET price = rec.new_price WHERE id = v_existing.id;
      v_updated := v_updated + 1;
    ELSE
      IF FOUND THEN
        UPDATE price_list_items SET valid_to = v_prev WHERE id = v_existing.id;
        v_closed := v_closed + 1;
      END IF;
      INSERT INTO price_list_items(price_list_id, product_id, price, valid_from)
      VALUES (v_pl_id, rec.product_id, rec.new_price, v_today);
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  RAISE NOTICE 'Updated: %, Inserted: %, Closed prev: %, Skipped uendret: %, Unmatched varenr: %',
    v_updated, v_inserted, v_closed, v_skipped, v_unmatched;
END $$;